```python
from string import ascii_lowercase, ascii_uppercase, digits, punctuation
import secrets

def generate_password(length=12):
    """Generate a secure random password."""
    if length < 4:
        raise ValueError("Password length should be at least 4 characters.")

    characters = (
        ascii_lowercase + 
        ascii_uppercase + 
        digits + 
        punctuation.replace('/', '').replace('"', '').replace("'", '')
    )

    if any(length < group_len for group_len in [len(ascii_lowercase), len(ascii_uppercase), len(digits)]):
        raise ValueError("Password length is too short to include all character types.")

    return ''.join(secrets.choice(characters) for _ in range(length))

# Example usage:
if __name__ == "__main__":
    print(generate_password())
